'use client'

import { useState } from 'react'
import { Upload, FileText, Palmtree, History } from 'lucide-react'
import { motion } from 'framer-motion'
import { PoliciesSection } from '@/components/shared/PoliciesSection'
import { HolidayManagerTab } from '@/components/shared/HolidayManagerTab'
import { PageHeader } from '@/components/shared/PageHeader'
import { AttendanceUploadTab } from '@/components/features/hr/AttendanceUploadTab'
import { AttendanceRecordsTab } from '@/components/features/hr/AttendanceRecordsTab'
import { cn } from '@/lib/utils/cn'

export default function HRAttendancePage() {
  const [tab, setTab] = useState<'attendance' | 'policy' | 'holiday'>('attendance')
  const [attendanceView, setAttendanceView] = useState<'upload' | 'records'>('upload')

  return (
    <div className="p-6 md:p-8 bg-[var(--color-page-bg)] min-h-screen space-y-6">
      <PageHeader
        title="Resources & Attendance"
        description="Manage employee records, policy documents, and system holidays"
      />

      <div className="flex items-center gap-1 bg-white border border-slate-200 rounded-2xl p-1 w-fit shadow-sm">
        {[
          { id: 'attendance', label: 'Attendance', icon: Upload },
          { id: 'policy', label: 'Policy Docs', icon: FileText },
          { id: 'holiday', label: 'Holidays', icon: Palmtree },
        ].map((t) => (
          <button
            key={t.id}
            onClick={() => setTab(t.id as any)}
            className={cn(
              "flex items-center gap-2 px-6 py-2.5 rounded-xl text-[11px] font-bold uppercase tracking-widest transition-all",
              tab === t.id
                ? "bg-blue-600 text-white shadow-lg shadow-blue-100"
                : "text-slate-400 hover:text-slate-600 hover:bg-slate-50"
            )}
          >
            <t.icon size={15} />
            {t.label}
          </button>
        ))}
      </div>

      {tab === 'attendance' && (
        <div className="space-y-6">
          <div className="flex items-center gap-2 bg-slate-100/50 rounded-xl p-1 w-fit">
            {[
              { id: 'upload', label: 'Upload Data', icon: Upload },
              { id: 'records', label: 'History & Audit', icon: History },
            ].map((v) => (
              <button
                key={v.id}
                onClick={() => setAttendanceView(v.id as any)}
                className={cn(
                  "flex items-center gap-2 px-4 py-1.5 rounded-lg text-[10px] font-bold uppercase tracking-widest transition-all",
                  attendanceView === v.id
                    ? "bg-white text-blue-600 shadow-sm border border-slate-200"
                    : "text-slate-500 hover:text-slate-700"
                )}
              >
                <v.icon size={12} />
                {v.label}
              </button>
            ))}
          </div>

          <motion.div
            key={attendanceView}
            initial={{ opacity: 0, y: 5 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.2 }}
          >
            {attendanceView === 'upload' ? <AttendanceUploadTab /> : <AttendanceRecordsTab />}
          </motion.div>
        </div>
      )}

      {tab === 'policy' && (
        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
          <PoliciesSection canUpload={true} />
        </motion.div>
      )}

      {tab === 'holiday' && (
        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
          <HolidayManagerTab />
        </motion.div>
      )}
    </div>
  )
}

'use client'

import { useMemo, useState } from 'react'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import { useMsal } from '@azure/msal-react'
import { Search, Trash2, UserCircle, Filter } from 'lucide-react'
import toast from 'react-hot-toast'
import { getAccessToken } from '@/lib/auth/getAccessToken'
import { PageHeader } from '@/components/shared/PageHeader'
import { EmptyState } from '@/components/shared/EmptyState'
import { ConfirmDialog } from '@/components/shared/ConfirmDialog'
import { ROLE_LABELS, ROLE_COLORS } from '@/constants/roles'
import { format } from 'date-fns'
import { cn } from '@/lib/utils/cn'
import { getInitials } from '@/lib/utils/formatters'
import { useCurrentUser } from '@/hooks/useCurrentUser'
import type { Role } from '@/constants/roles'

interface AdminUser {
  id: string
  displayName: string
  email: string
  entraObjectId?: string
  role: Role
  employmentStatus: string
  jobTitle?: string | null
  joinDate: string
}

const ROLE_OPTIONS: Role[] = ['EMPLOYEE', 'MANAGER', 'HR']

export default function AdminUsersPage() {
  const { instance } = useMsal()
  const queryClient = useQueryClient()
  const { data: currentUserData } = useCurrentUser()
  const currentUserId = currentUserData?.user?.id

  const [roleFilter, setRoleFilter] = useState<string>('ALL')
  const [statusFilter, setStatusFilter] = useState<string>('ALL')
  const [search, setSearch] = useState('')
  const [userToDelete, setUserToDelete] = useState<AdminUser | null>(null)
  const [isDeleting, setIsDeleting] = useState(false)

  const { data: users = [], isLoading } = useQuery<AdminUser[]>({
    queryKey: ['adminUsers'],
    queryFn: async () => {
      const token = await getAccessToken(instance)
      const res = await fetch('/api/hr/users', { headers: { Authorization: `Bearer ${token}` } })
      if (!res.ok) throw new Error('Failed to load users')
      return res.json()
    },
  })

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase()
    return users
      .filter((u) => roleFilter === 'ALL' || u.role === roleFilter)
      .filter((u) => statusFilter === 'ALL' || u.employmentStatus === statusFilter)
      .filter((u) => {
        if (!q) return true
        const hay = [u.displayName, u.email, u.jobTitle ?? '']
          .join(' ')
          .toLowerCase()
        return hay.includes(q)
      })
  }, [users, roleFilter, statusFilter, search])

  async function handleDeleteUser() {
    if (!userToDelete) return
    setIsDeleting(true)
    try {
      const token = await getAccessToken(instance)
      const res = await fetch(`/api/hr/users/${userToDelete.id}`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${token}` },
      })
      const data = await res.json()
      if (!res.ok) throw new Error(data.error ?? 'Failed to delete user')
      toast.success(`${userToDelete.displayName} removed from system`)
      setUserToDelete(null)
      queryClient.invalidateQueries({ queryKey: ['adminUsers'] })
    } catch (err: any) {
      toast.error(err.message ?? 'Failed to delete user')
    } finally {
      setIsDeleting(false)
    }
  }

  return (
    <div className="p-6 md:p-8 bg-[var(--color-page-bg)] min-h-screen space-y-6">
      <PageHeader 
        title="User & Access Management" 
        description="Configure system access and manage synced workforce accounts." 
        badge={users.length} 
      />

      <div className="flex flex-wrap gap-4 items-center">
        <div className="flex items-center gap-4 flex-1 min-w-[300px] bg-white border border-slate-200 rounded-2xl px-5 py-3 shadow-sm focus-within:ring-4 focus-within:ring-blue-500/5 focus-within:border-blue-300 transition-all group">
          <Search size={18} className="text-slate-400 group-focus-within:text-blue-500 transition-colors" />
          <input
            type="search"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search name, email, or job title..."
            className="flex-1 bg-transparent border-none outline-none text-sm font-semibold text-slate-700 placeholder:text-slate-400"
          />
        </div>

        <div className="flex items-center gap-2 bg-slate-100/80 p-1.5 rounded-2xl border border-slate-200 shadow-inner">
          <div className="flex items-center gap-2 px-3 text-slate-400 border-r border-slate-200 mr-1">
            <Filter size={14} />
            <span className="text-[10px] font-bold uppercase tracking-widest">Filters</span>
          </div>
          <select 
            value={roleFilter} 
            onChange={e => setRoleFilter(e.target.value)}
            className="bg-transparent text-[11px] font-bold uppercase tracking-widest text-slate-600 outline-none cursor-pointer hover:text-blue-600 transition-colors"
          >
            <option value="ALL">All Roles</option>
            {ROLE_OPTIONS.map(r => <option key={r} value={r}>{ROLE_LABELS[r]}</option>)}
          </select>
          <select 
            value={statusFilter} 
            onChange={e => setStatusFilter(e.target.value)}
            className="bg-transparent text-[11px] font-bold uppercase tracking-widest text-slate-600 outline-none cursor-pointer hover:text-blue-600 transition-colors ml-4 mr-2"
          >
            <option value="ALL">All Statuses</option>
            <option value="ACTIVE">Active</option>
            <option value="INACTIVE">Inactive</option>
            <option value="TERMINATED">Terminated</option>
          </select>
        </div>
      </div>

      {isLoading ? (
        <div className="text-center py-20">
          <p className="text-[11px] font-bold text-slate-400 uppercase tracking-[0.2em] animate-pulse">Loading system users...</p>
        </div>
      ) : filtered.length === 0 ? (
        <EmptyState icon="👤" title="No users found" description="No workforce accounts match the current filters." />
      ) : (
        <div className="bg-white border border-slate-200 rounded-2xl overflow-hidden shadow-sm">
          <div className="overflow-x-auto">
            <table className="w-full border-collapse">
              <thead>
                <tr className="bg-slate-50/80 border-b border-slate-100">
                  <th className="px-6 py-4 text-left text-[10px] font-bold uppercase tracking-[0.2em] text-slate-400">Employee</th>
                  <th className="px-6 py-4 text-left text-[10px] font-bold uppercase tracking-[0.2em] text-slate-400">Entra ID</th>
                  <th className="px-6 py-4 text-left text-[10px] font-bold uppercase tracking-[0.2em] text-slate-400">Role</th>
                  <th className="px-6 py-4 text-left text-[10px] font-bold uppercase tracking-[0.2em] text-slate-400">Status</th>
                  <th className="px-6 py-4 text-left text-[10px] font-bold uppercase tracking-[0.2em] text-slate-400">Join Date</th>
                  <th className="px-6 py-4 text-right text-[10px] font-bold uppercase tracking-[0.2em] text-slate-400">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {filtered.map(user => (
                  <tr key={user.id} className="group hover:bg-slate-50/50 transition-colors">
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-4">
                        <div className="w-10 h-10 rounded-full bg-blue-50 border-2 border-white shadow-sm flex items-center justify-center text-blue-600 text-[13px] font-bold shrink-0 transition-transform group-hover:scale-105">
                          {getInitials(user.displayName)}
                        </div>
                        <div>
                          <p className="text-[13px] font-bold text-slate-900 leading-tight group-hover:text-blue-700 transition-colors">{user.displayName}</p>
                          <a
                            href={`mailto:${user.email}`}
                            className="text-[11px] font-medium text-slate-400 hover:text-blue-600 transition-colors"
                            onClick={e => e.stopPropagation()}
                          >
                            {user.email}
                          </a>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2">
                        <UserCircle size={14} className="text-slate-300" />
                        <span className="font-mono text-[11px] text-slate-500 font-medium">
                          {user.entraObjectId?.startsWith('pending-') ? '⏳ PENDING SYNC' : (user.entraObjectId?.slice(0, 12).toUpperCase() + '...')}
                        </span>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className={cn(
                        'text-[10px] px-2 py-0.5 rounded-lg font-black uppercase tracking-widest border shadow-sm', 
                        ROLE_COLORS[user.role] || 'bg-slate-50 text-slate-500'
                      )}>
                        {ROLE_LABELS[user.role] || user.role}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <span className={cn(
                        "inline-flex items-center px-2.5 py-1 rounded-lg text-[10px] font-bold uppercase tracking-tight border",
                        user.employmentStatus === 'ACTIVE' ? 'bg-emerald-50 text-emerald-700 border-emerald-100' :
                        user.employmentStatus === 'TERMINATED' ? 'bg-red-50 text-red-700 border-red-100' :
                        'bg-slate-50 text-slate-500 border-slate-100'
                      )}>
                        {user.employmentStatus}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <span className="text-[12px] font-bold text-slate-500">
                        {(() => { try { return format(new Date(user.joinDate), 'dd MMM yyyy') } catch { return '—' } })()}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      {user.role !== 'HR' && user.id !== currentUserId && (
                        <button
                          onClick={() => setUserToDelete(user)}
                          className="p-2 text-slate-300 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all opacity-0 group-hover:opacity-100"
                          title="Remove from system"
                        >
                          <Trash2 size={16} />
                        </button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="px-6 py-3 bg-slate-50/50 border-t border-slate-100">
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
              Showing {filtered.length} of {users.length} workforce accounts
            </p>
          </div>
        </div>
      )}

      <ConfirmDialog
        isOpen={!!userToDelete}
        onClose={() => setUserToDelete(null)}
        onConfirm={handleDeleteUser}
        title="Permanently Remove Account"
        description={`This will immediately remove ${userToDelete?.displayName ?? 'this user'} and all associated records from the HRM system. Their Azure Entra ID credentials will remain untouched, but they will lose all historical LMS data.`}
        confirmLabel="Remove Permanently"
        variant="danger"
        isLoading={isDeleting}
      />
    </div>
  )
}

'use client'

import { motion } from 'framer-motion'
import { PageHeader } from '@/components/shared/PageHeader'
import { ConfirmDialog } from '@/components/shared/ConfirmDialog'
import { EmptyState } from '@/components/shared/EmptyState'
import { TableSkeleton } from '@/components/shared/LoadingSkeleton'
import { useManagerApprovals } from '@/hooks/useManagerApprovals'
import { LeaveApprovalCard } from '@/components/features/manager/LeaveApprovalCard'
import { cn } from '@/lib/utils/cn'

export default function ManagerApprovalsPage() {
  const {
    approvals,
    isLoading,
    filter,
    setFilter,
    selectedLeave,
    setSelectedLeave,
    approveDialogOpen,
    setApproveDialogOpen,
    rejectDialogOpen,
    setRejectDialogOpen,
    rejectionReason,
    setRejectionReason,
    approvalReason,
    setApprovalReason,
    handleAction,
    isProcessing,
  } = useManagerApprovals()

  const filters: { label: string; value: typeof filter }[] = [
    { label: 'Pending', value: 'PENDING' },
    { label: 'Approved', value: 'APPROVED' },
    { label: 'Rejected', value: 'REJECTED' },
    { label: 'All Requests', value: 'ALL' },
  ]

  return (
    <motion.div
      initial={{ opacity: 0, x: -8 }}
      animate={{ opacity: 1, x: 0 }}
      transition={{ duration: 0.25 }}
      className="p-6 md:p-8 bg-[var(--color-page-bg)] min-h-screen space-y-6"
    >
      <PageHeader
        title="Team Approvals"
        description="Review and act on pending leave requests from your team members."
        badge={approvals.length}
      />

      <FilterTabs active={filter} options={filters} onChange={setFilter} />

      {isLoading ? (
        <div className="bg-[var(--color-card-bg)] border border-[var(--color-card-border)] rounded-2xl overflow-hidden shadow-sm">
          <TableSkeleton />
        </div>
      ) : approvals.length === 0 ? (
        <EmptyState 
          icon="✨" 
          title="All caught up!" 
          description={filter === 'PENDING' ? "No pending approvals found. Your team is set." : "No records found for this filter."} 
        />
      ) : (
        <div className="grid grid-cols-1 gap-4">
          {approvals.map((leave) => (
            <LeaveApprovalCard
              key={leave.id}
              leave={leave}
              onApprove={() => {
                setSelectedLeave(leave)
                setApproveDialogOpen(true)
              }}
              onReject={() => {
                setSelectedLeave(leave)
                setRejectDialogOpen(true)
              }}
            />
          ))}
        </div>
      )}

      {/* Approve Dialog */}
      <ConfirmDialog
        isOpen={approveDialogOpen}
        onClose={() => setApproveDialogOpen(false)}
        onConfirm={() =>
          selectedLeave &&
          handleAction({ id: selectedLeave.id, action: 'approve', reason: approvalReason })
        }
        title="Approve Request"
        description={`Are you sure you want to approve leave for ${selectedLeave?.employee?.displayName}?`}
        confirmLabel="Approve"
        isLoading={isProcessing}
      >
        <div className="mt-4">
          <label className="block text-xs font-bold text-slate-500 uppercase tracking-widest mb-2 ml-1">
            Internal Comments (Optional)
          </label>
          <textarea
            value={approvalReason}
            onChange={(e) => setApprovalReason(e.target.value)}
            rows={3}
            placeholder="Add any context for this approval..."
            className="w-full bg-slate-50 border border-[var(--color-card-border)] rounded-xl px-4 py-3 text-sm text-[var(--color-heading)] outline-none focus:ring-2 focus:ring-blue-500/20 resize-none transition-all"
          />
        </div>
      </ConfirmDialog>

      {/* Reject Dialog */}
      <ConfirmDialog
        isOpen={rejectDialogOpen}
        onClose={() => {
          setRejectDialogOpen(false)
          setRejectionReason('')
        }}
        onConfirm={() =>
          selectedLeave &&
          handleAction({ id: selectedLeave.id, action: 'reject', reason: rejectionReason })
        }
        title="Reject Request"
        description={`Please provide a reason for rejecting leave for ${selectedLeave?.employee?.displayName}.`}
        confirmLabel="Reject"
        variant="danger"
        isLoading={isProcessing}
      >
        <div className="mt-4">
          <label className="block text-xs font-bold text-red-500 uppercase tracking-widest mb-2 ml-1">
            Reason for Rejection *
          </label>
          <textarea
            value={rejectionReason}
            onChange={(e) => setRejectionReason(e.target.value)}
            rows={3}
            placeholder="The employee will see this reason..."
            className="w-full bg-red-50/30 border border-red-100 rounded-xl px-4 py-3 text-sm text-[var(--color-heading)] outline-none focus:ring-2 focus:ring-red-500/20 resize-none transition-all"
          />
        </div>
      </ConfirmDialog>
    </motion.div>
  )
}

function FilterTabs({ active, options, onChange }: { active: string, options: { label: string; value: string }[], onChange: (v: any) => void }) {
  return (
    <div className="flex items-center gap-2 bg-[var(--color-card-bg)] border border-[var(--color-card-border)] rounded-2xl p-1.5 w-fit shadow-sm">
      {options.map((f) => (
        <button
          key={f.value}
          onClick={() => onChange(f.value)}
          className={cn(
            "px-5 py-2 rounded-xl text-xs font-bold transition-all",
            active === f.value
              ? "bg-blue-600 text-white shadow-md shadow-blue-100"
              : "text-[var(--color-muted)] hover:text-[var(--color-heading)] hover:bg-slate-50"
          )}
        >
          {f.label}
        </button>
      ))}
    </div>
  )
}

'use client'

import { useRef, useState } from 'react'
import { useRouter } from 'next/navigation'
import { useQueryClient } from '@tanstack/react-query'
import { useMsal } from '@azure/msal-react'
import { motion } from 'framer-motion'
import { format } from 'date-fns'
import { Camera, ChevronRight, Briefcase, Mail, Phone, Calendar, UserCheck, Shield } from 'lucide-react'
import toast from 'react-hot-toast'

import { useCurrentUser } from '@/hooks/useCurrentUser'
import { PageHeader } from '@/components/shared/PageHeader'
import { PageSkeleton } from '@/components/shared/LoadingSkeleton'
import { getInitials, getCleanFirstName } from '@/lib/utils/formatters'
import { ROLE_COLORS, ROLE_LABELS } from '@/constants/roles'
import { getAccessToken } from '@/lib/auth/getAccessToken'

export default function ProfilePage() {
  const router = useRouter()
  const { instance } = useMsal()
  const queryClient = useQueryClient()
  const { data, isLoading, isError } = useCurrentUser()
  const fileInputRef = useRef<HTMLInputElement>(null)
  const [uploading, setUploading] = useState(false)

  if (isLoading) return <PageSkeleton />
  if (isError || !data) return null

  const { user, balance } = data
  const firstName = getCleanFirstName(user?.firstName, user?.displayName)

  const getBal = (type: string) => 
    balance.balances.find((b: any) => b.type === type) || { total: 0, consumed: 0, inApproval: 0 }

  const std = getBal('ANNUAL')
  const emg = getBal('EMERGENCY')
  const flt = getBal('FLOATER')

  const handlePhotoChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return
    setUploading(true)
    try {
      const token = await getAccessToken(instance)
      const formData = new FormData()
      formData.append('photo', file)
      const res = await fetch('/api/profile/photo', {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}` },
        body: formData,
      })
      if (!res.ok) throw new Error('Upload failed')
      await queryClient.invalidateQueries({ queryKey: ['currentUser'] })
      toast.success('Profile photo updated')
    } catch (err: any) {
      toast.error(err.message ?? 'Failed to upload photo')
    } finally {
      setUploading(false)
      if (fileInputRef.current) fileInputRef.current.value = ''
    }
  }

  return (
    <motion.div
      initial={{ opacity: 0, x: -8 }}
      animate={{ opacity: 1, x: 0 }}
      className="p-6 md:p-8 bg-[var(--color-page-bg)] min-h-screen flex flex-col gap-6"
    >
      <PageHeader 
        title={`Welcome, ${firstName}`} 
        description="Your personal details, leave summary, and quick actions." 
      />

      <div className="grid grid-cols-1 xl:grid-cols-2 gap-8 items-start">
        {/* Identity & Personal Info Section */}
        <section className="bg-[var(--color-card-bg)] border border-[var(--color-card-border)] rounded-2xl p-6 md:p-8 shadow-sm space-y-8">
          <div className="flex flex-col sm:flex-row items-center gap-6">
            {/* Avatar Section */}
            <div
              className="relative w-24 h-24 rounded-full bg-slate-800 flex items-center justify-center text-white text-3xl font-bold overflow-hidden cursor-pointer group shadow-lg"
              onClick={() => !uploading && fileInputRef.current?.click()}
            >
              {uploading ? (
                <div className="w-8 h-8 border-2 border-white border-t-transparent rounded-full animate-spin" />
              ) : user.profilePictureUrl ? (
                <img src={user.profilePictureUrl} alt={user.displayName} className="w-full h-full object-cover" />
              ) : (
                getInitials(user.displayName)
              )}
              {!uploading && (
                <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 flex flex-col items-center justify-center transition-opacity">
                  <Camera size={20} className="text-white" />
                  <span className="text-white text-[10px] font-bold mt-1 uppercase tracking-tighter">Update</span>
                </div>
              )}
              <input ref={fileInputRef} type="file" accept="image/jpeg,image/png" className="hidden" onChange={handlePhotoChange} />
            </div>

            <div className="text-center sm:text-left space-y-2">
              <h2 className="text-2xl font-bold text-[var(--color-heading)] tracking-tight">{user.displayName}</h2>
              <div className="flex flex-wrap justify-center sm:justify-start gap-2">
                <span className={`inline-flex items-center rounded-lg px-3 py-1 text-[10px] font-bold uppercase tracking-widest ${ROLE_COLORS[user.role]}`}>
                  {ROLE_LABELS[user.role]}
                </span>
                <span className="bg-slate-100 text-slate-600 border border-slate-200 px-3 py-1 rounded-lg text-[10px] font-bold uppercase tracking-widest">
                  {user.employmentStatus}
                </span>
              </div>
            </div>
          </div>

