            <ProfileField label="Phone Number" value={user.phoneNumber} icon={<Phone size={14} />} />
            <ProfileField 
              label="Join Date" 
              value={user.joinDate ? format(new Date(user.joinDate), 'MMMM dd, yyyy') : '—'} 
