import { NextRequest, NextResponse } from 'next/server'
import { validateToken, requireRole } from '@/lib/auth/validateToken'
import { prisma } from '@/lib/db/prisma'
import { AuditAction } from '@prisma/client'

export async function GET(req: NextRequest) {
  try {
    const token = await validateToken(req)
    requireRole(token, ['HR'])

    const { searchParams } = new URL(req.url)
    const action = searchParams.get('action')
    const page = parseInt(searchParams.get('page') ?? '1')
    const pageSize = parseInt(searchParams.get('pageSize') ?? '50')

    const logs = await prisma.auditLog.findMany({
      where: action ? { action: action as any } : {},
      include: {
        target: { select: { id: true, displayName: true, workEmail: true } },
        performer: { select: { id: true, displayName: true, workEmail: true } },
      },
      orderBy: { createdAt: 'desc' },
      take: pageSize,
      skip: (page - 1) * pageSize,
    })

    return NextResponse.json(
      logs.map((log) => ({
        ...log,
        createdAt: log.createdAt ? log.createdAt.toISOString() : new Date().toISOString(),
      }))
    )
  } catch (err: any) {
    console.error('[API/HR/AUDIT] Global Error:', err)
    
    return NextResponse.json({ 
      error: 'Failed to fetch audit logs', 
      details: err.message || String(err),
      stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
      code: 'INTERNAL_ERROR' 
    }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { validateToken, requireRole } from '@/lib/auth/validateToken'
import { prisma } from '@/lib/db/prisma'
import * as XLSX from 'xlsx'

export async function GET(req: NextRequest) {
  const token = await validateToken(req)
  requireRole(token, ['HR'])

  const { searchParams } = new URL(req.url)
  const format = (searchParams.get('format') ?? 'xlsx').toLowerCase()

  if (!['xlsx', 'csv', 'pdf'].includes(format)) {
    return NextResponse.json({ error: 'format must be xlsx, csv, or pdf' }, { status: 400 })
  }

  const employees = await prisma.employee.findMany({
    where: { employmentStatus: { not: 'TERMINATED' } },
    include: {
      manager:      { select: { displayName: true, workEmail: true } },
      leaveBalance: true,
    },
    orderBy: { firstName: 'asc' },
  })

  const rows = employees.map(emp => ({
    'Azure Object ID':        emp.entraObjectId,
    'Display Name':           emp.displayName,
    'First Name':             emp.firstName,
    'Last Name':              emp.lastName,
    'Email':                  emp.workEmail,
    'Notification Email':     emp.notificationEmail  ?? '',
    'Job Title':              emp.jobTitle          ?? '',
    'Role':                   emp.role,
    'Employment Status':      emp.employmentStatus,
    'Phone Number':           emp.phoneNumber        ?? '',
    'Emergency Contact Name': (emp as any).emergencyName     ?? '',
    'Emergency Relation':     (emp as any).emergencyRelation ?? '',
    'Emergency Phone':        (emp as any).emergencyPhone    ?? '',
    'Manager Name':           emp.manager?.displayName ?? '',
    'Manager Email':          emp.manager?.workEmail       ?? '',
    'Join Date':              emp.joinDate
                                ? new Date(emp.joinDate).toLocaleDateString('en-IN')
                                : '',
    'Standard Leave Total':   emp.leaveBalance?.standardTotal  ?? 18,
    'Standard Leave Used':    emp.leaveBalance?.standardUsed   ?? 0,
    'Floater Leave Total':    emp.leaveBalance?.floaterTotal   ?? 2,
    'Floater Leave Used':     emp.leaveBalance?.floaterUsed    ?? 0,
    'Emergency Leave Total':  emp.leaveBalance?.emergencyTotal ?? 2,
    'Emergency Leave Used':   emp.leaveBalance?.emergencyUsed  ?? 0,
  }))

  const filename = `employees_${new Date().toISOString().split('T')[0]}`

  // ── XLSX / CSV ──────────────────────────────────────────────────────────────
  if (format === 'xlsx' || format === 'csv') {
    const ws = XLSX.utils.json_to_sheet(rows)

    // Auto-size columns
    const colWidths = Object.keys(rows[0] ?? {}).map(key => ({
      wch: Math.max(key.length, 15)
    }))
    ws['!cols'] = colWidths

    const wb = XLSX.utils.book_new()
    XLSX.utils.book_append_sheet(wb, ws, 'Employees')

    if (format === 'xlsx') {
      const buf = XLSX.write(wb, { type: 'buffer', bookType: 'xlsx' })
      return new NextResponse(buf, {
        headers: {
          'Content-Type': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
          'Content-Disposition': `attachment; filename="${filename}.xlsx"`,
        },
      })
    } else {
      const csv = XLSX.utils.sheet_to_csv(ws)
      return new NextResponse(csv, {
        headers: {
          'Content-Type': 'text/csv',
          'Content-Disposition': `attachment; filename="${filename}.csv"`,
        },
      })
    }
  }

  // ── PDF ─────────────────────────────────────────────────────────────────────
  if (format === 'pdf') {
    // Build a simple HTML table and return it as an HTML file the browser can print-to-PDF
    // (Avoids server-side PDF dependencies — the user uses browser Print → Save as PDF)
    const tableRows = rows.map(row =>
      `<tr>${Object.values(row).map(v => `<td>${String(v).replace(/</g, '&lt;')}</td>`).join('')}</tr>`
    ).join('\n')

    const headers = Object.keys(rows[0] ?? {})
      .map(h => `<th>${h}</th>`).join('')

    const html = `<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <title>Employee Export — ${filename}</title>
  <style>
    body { font-family: Segoe UI, Arial, sans-serif; font-size: 11px; margin: 24px; }
    h2 { color: #1e293b; margin-bottom: 16px; }
    table { border-collapse: collapse; width: 100%; }
    th { background: #6366f1; color: white; padding: 6px 8px; text-align: left; font-size: 10px; white-space: nowrap; }
    td { padding: 5px 8px; border-bottom: 1px solid #e2e8f0; vertical-align: top; }
    tr:nth-child(even) td { background: #f8fafc; }
    @media print { body { margin: 0; } }
  </style>
</head>
<body>
  <h2>Employee Directory — ${new Date().toLocaleDateString('en-IN', { day: '2-digit', month: 'long', year: 'numeric' })}</h2>
  <p style="color:#64748b;margin-bottom:16px;">Total: ${rows.length} employees · Generated by Monkstack HRM</p>
  <table>
    <thead><tr>${headers}</tr></thead>
    <tbody>${tableRows}</tbody>
  </table>
  <script>window.onload = function() { window.print(); }</script>
</body>
</html>`

    return new NextResponse(html, {
      headers: {
        'Content-Type': 'text/html; charset=utf-8',
        'Content-Disposition': `inline; filename="${filename}.html"`,
      },
    })
  }

  return NextResponse.json({ error: 'Invalid format' }, { status: 400 })
}

import { NextRequest, NextResponse } from 'next/server'
import { validateToken, requireRole } from '@/lib/auth/validateToken'
import { prisma } from '@/lib/db/prisma'
import { getAvailabilityForDate } from '@/lib/utils/dateUtils'

export async function GET(req: NextRequest) {
  try {
    const token = await validateToken(req)
    requireRole(token, ['HR'])

    const { searchParams } = new URL(req.url)
    const statusFilter = searchParams.get('status')

    const today = new Date()
    today.setHours(0, 0, 0, 0)
    const todayEnd = new Date()
    todayEnd.setHours(23, 59, 59, 999)

    const employees = await prisma.employee.findMany({
      where: statusFilter ? { employmentStatus: statusFilter as 'ACTIVE' | 'INACTIVE' | 'TERMINATED' } : undefined,
      include: {
        manager: { select: { id: true, displayName: true } },
        leaveRequests: {
          where: { status: 'APPROVED', startDate: { lte: todayEnd }, endDate: { gte: today } },
        },
      },
      orderBy: { firstName: 'asc' },
    })

    const result = employees.map((emp) => {
      const availabilityStatus = getAvailabilityForDate(
        emp.leaveRequests.map((lr) => ({
          startDate: lr.startDate,
          endDate: lr.endDate,
          startHalfDay: lr.startHalfDay,
          endHalfDay: lr.endHalfDay,
          status: lr.status,
        })),
        today
      )

      return {
        id: emp.id,
        entraObjectId: emp.entraObjectId,
        email: emp.workEmail,
        workEmail: emp.workEmail,
        notificationEmail: emp.notificationEmail,
        displayName: emp.displayName,
        firstName: emp.firstName,
        lastName: emp.lastName,
        jobTitle: emp.jobTitle,
        phoneNumber: emp.phoneNumber,
        emergencyName: (emp as any).emergencyName,
        emergencyRelation: (emp as any).emergencyRelation,
        emergencyPhone: (emp as any).emergencyPhone,
        profilePictureUrl: emp.profilePictureUrl,
        role: emp.role,
        employmentStatus: emp.employmentStatus,
        managerId: emp.managerId,
        managerName: emp.manager?.displayName ?? null,
        joinDate: emp.joinDate.toISOString(),
        terminationDate: emp.terminationDate?.toISOString() ?? null,
        createdAt: emp.createdAt.toISOString(),
        updatedAt: emp.updatedAt.toISOString(),
        availabilityStatus,
      }
    })

    return NextResponse.json(result)
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Unknown'
    if (message === 'UNAUTHORIZED') return NextResponse.json({ error: 'Unauthorized', code: 'UNAUTHORIZED' }, { status: 401 })
    if (message === 'FORBIDDEN') return NextResponse.json({ error: 'Forbidden', code: 'FORBIDDEN' }, { status: 403 })
    return NextResponse.json({ error: 'Internal server error', code: 'INTERNAL_ERROR' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { validateToken, requireRole } from '@/lib/auth/validateToken'
import { prisma } from '@/lib/db/prisma'
import { calculateProratedLeaves, calculateProratedFloaterLeaves, calculateProratedEmergencyLeaves } from '@/lib/leave/prorateService'

export async function POST(req: NextRequest) {
  try {
    const token = await validateToken(req)
    requireRole(token, ['HR'])

    const year = new Date().getFullYear()
    const employees = await prisma.employee.findMany({
      where: { employmentStatus: 'ACTIVE' },
      select: { id: true, displayName: true, joinDate: true },
    })

    const results = []
    for (const emp of employees) {
      const std   = calculateProratedLeaves(emp.joinDate, 18, year)
      const flt   = calculateProratedFloaterLeaves(emp.joinDate, 2, year)
      const emer  = calculateProratedEmergencyLeaves(emp.joinDate, 2, year)

      await prisma.leaveBalance.upsert({
        where: { employeeId: emp.id },
        create: {
          employeeId: emp.id, year,
          standardTotal: std, standardAccrued: std, standardUsed: 0, standardCarryForward: 0,
          floaterTotal: flt, floaterUsed: 0,
          emergencyTotal: emer, emergencyUsed: 0,
        },
        update: {
          year, standardTotal: std, floaterTotal: flt, emergencyTotal: emer,
        },
      })
      results.push({ name: emp.displayName, std, flt, emer })
    }

    return NextResponse.json({ message: `Fixed ${results.length} balances`, results })
  } catch (err: any) {
    return NextResponse.json({ error: err.message }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { validateToken, requireRole } from '@/lib/auth/validateToken'
import { prisma } from '@/lib/db/prisma'
import { parse, parseISO } from 'date-fns'

export async function POST(req: NextRequest) {
  try {
    const token = await validateToken(req)
    requireRole(token, ['HR'])

    const holidays: Array<{ name: string; date: string; type?: string; notes?: string }> = await req.json()
    if (!Array.isArray(holidays)) {
      return NextResponse.json({ error: 'Expected JSON array' }, { status: 400 })
    }

    let processed = 0
    const errors: string[] = []

    for (const h of holidays) {
      try {
        if (!h.name || !h.date) {
          errors.push(`Missing name or date for record: ${JSON.stringify(h)}`)
          continue
        }

        let dateObj: Date
        const dateStr = h.date.trim()
        
        if (dateStr.includes('-')) {
          const parts = dateStr.split('-')
          if (parts[0].length === 4) {
            dateObj = parse(dateStr, 'yyyy-MM-dd', new Date())
          } else {
            dateObj = parse(dateStr, 'dd-MM-yyyy', new Date())
          }
        } else if (dateStr.includes('/')) {
          const parts = dateStr.split('/')
          if (parts[0].length === 4) {
            dateObj = parse(dateStr, 'yyyy/MM/dd', new Date())
          } else {
            dateObj = parse(dateStr, 'dd/MM/yyyy', new Date())
          }
        } else {
          dateObj = parseISO(dateStr)
        }

        if (isNaN(dateObj.getTime())) {
          throw new Error(`Invalid date format: ${dateStr}`)
        }

        await prisma.publicHoliday.create({
          data: {
            name: h.name,
            date: dateObj,
            type: (h.type?.toUpperCase() === 'FLOATER' ? 'FLOATER' : 'PUBLIC') as any,
            notes: h.notes || null,
            createdBy: token.userId
          }
        })
        processed++
      } catch (err: unknown) {
        errors.push(`Error processing ${h.name}: ${err instanceof Error ? err.message : String(err)}`)
      }
    }

    return NextResponse.json({ processed, errors })
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Unknown'
    if (message === 'UNAUTHORIZED') return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    if (message === 'FORBIDDEN') return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { validateToken, requireRole } from '@/lib/auth/validateToken'
import { prisma } from '@/lib/db/prisma'
import { logAudit } from '@/lib/audit/auditLogger'
import { getAppAccessToken } from '@/lib/auth/graphClient'
import type { Role } from '@prisma/client'
import { sendMail } from '@/lib/email/acsMailer'
import { wrapEmailBody, detailRow, detailCard } from '@/lib/email/templates/shared'
import { getNotificationEmail } from '@/lib/email/getNotificationEmail'

export async function PATCH(
  req: NextRequest,
  { params }: { params: { id: string } }
) {
  try {
    const token = await validateToken(req)
    requireRole(token, ['HR'])

    const body = await req.json()
    const { role } = body
    const nextRole = role as Role

    if (!['EMPLOYEE', 'MANAGER', 'HR'].includes(nextRole)) {
      return NextResponse.json({ error: 'Invalid role' }, { status: 400 })
    }

    const { id: rawIdentifier } = params
    const employee = await prisma.employee.findFirst({
      where: {
        OR: [
          { id: rawIdentifier },
          { entraObjectId: rawIdentifier },
          { workEmail: { equals: rawIdentifier, mode: 'insensitive' } },
        ],
      },
    })

    if (!employee) return NextResponse.json({ error: 'Employee not found' }, { status: 404 })
    if (employee.id === token.userId) {
      return NextResponse.json({ error: 'Cannot change your own role' }, { status: 403 })
    }

    const oldRole = employee.role
    if (oldRole === nextRole) return NextResponse.json({ success: true, role: nextRole })

    // Part 7.1: Sync Entra groups FIRST
    if (employee.entraObjectId && !employee.entraObjectId.startsWith('pending-')) {
      try {
        const accessToken = await getAppAccessToken()

        const roleGroupEnvMap: Record<string, string | undefined> = {
          EMPLOYEE: process.env.ENTRA_GROUP_ID_LMS_EMPLOYEES,
          MANAGER: process.env.ENTRA_GROUP_ID_LMS_MANAGERS,
          HR: process.env.ENTRA_GROUP_ID_LMS_HR,
        }

        const oldGroupId = roleGroupEnvMap[oldRole]
        const newGroupId = roleGroupEnvMap[nextRole]

        // 1. Remove from old group
        if (oldGroupId) {
          const resDelete = await fetch(`https://graph.microsoft.com/v1.0/groups/${oldGroupId}/members/${employee.entraObjectId}/$ref`, {
            method: 'DELETE',
            headers: { Authorization: `Bearer ${accessToken}` },
          })
          if (!resDelete.ok && resDelete.status !== 404) {
            const errBody = await resDelete.text()
            throw new Error(`Failed to remove from old group: ${errBody}`)
          }
        }

        // 2. Add to new group
        if (newGroupId) {
          const resPost = await fetch(`https://graph.microsoft.com/v1.0/groups/${newGroupId}/members/$ref`, {
            method: 'POST',
            headers: { Authorization: `Bearer ${accessToken}`, 'Content-Type': 'application/json' },
            body: JSON.stringify({ '@odata.id': `https://graph.microsoft.com/v1.0/directoryObjects/${employee.entraObjectId}` }),
          })
          if (!resPost.ok && resPost.status !== 409) { // 409 means already a member
            const errBody = await resPost.text()
            throw new Error(`Failed to add to new group: ${errBody}`)
          }
        }
      } catch (graphErr: any) {
        console.error('[role-change] Entra sync error (FATAL):', graphErr)
        return NextResponse.json({ 
          error: 'Failed to sync with Azure Entra ID. Security role was not updated in database. Please ensure groups are correctly configured in .env', 
          details: graphErr.message 
        }, { status: 500 })
      }
    }

    // Notify employee
    await prisma.notification.create({
      data: {
        type: 'ROLE_CHANGED',
        title: 'Your Role Has Been Updated',
        message: `Your role has been changed from ${oldRole} to ${nextRole}. Please log out and back in to see the changes.`,
        recipientId: employee.id,
        senderId: token.userId,
      },
    })

    await logAudit('ROLE_CHANGE', token.userId, employee.id, {
      before: { role: oldRole },
      after: { role: nextRole },
      params: {},
    }, req)

    // Send Email
    const appBaseUrl = process.env.NEXTAUTH_URL ?? 'http://localhost:3000'
    const rows = [
      detailRow('Previous Role', oldRole),
      detailRow('New Role',      nextRole),
      detailRow('Effective',     'Immediately — please log out and log back in'),
    ].join('\n')

    const htmlBody = wrapEmailBody({
      preheader:  'Your role in Monkstack HRM has been updated',
      badgeText:  '🔄 Role Updated',
      badgeColor: 'blue',
      headline:   'Your access role has been updated',
      bodyHtml:   `<p style="color:#475569;font-size:14px;line-height:1.6;margin:0 0 20px;">
                     Your role in the Monkstack HRM system has been changed. 
                     Please log out and log back in for the new permissions to take effect.
                     If you believe this is an error, contact HR immediately.
                   </p>${detailCard(rows)}`,
      buttons: [{ label: 'Go to Login', url: `${appBaseUrl}/login` }],
    })
    const subject = `[Monkstack HRM] Your role has been updated to ${nextRole}`

    await sendMail({ to: [getNotificationEmail(employee)], subject, htmlBody }).catch(console.error)

    return NextResponse.json({
      success: true,
      message: `Role update submitted to Azure. ${employee.displayName} will see the change on their next login.`,
      pendingRole: nextRole,
    })
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Unknown'
    if (message === 'UNAUTHORIZED') return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    if (message === 'FORBIDDEN') return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
    console.error('[role-change] Error:', err)
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { validateToken } from '@/lib/auth/validateToken'
import { prisma } from '@/lib/db/prisma'
import { format, isWeekend, parseISO } from 'date-fns'
import { computeTotalDays, formatDateRange } from '@/lib/utils/dateUtils'
import { validateLeaveDates, validateBalance, validateSandwichRule } from '@/lib/leave/leaveValidator'
import { getLeaveBalance } from '@/lib/leave/balanceService'
import { createNotifications, notifyLeaveApplied } from '@/lib/notifications/notificationService'
import { logAudit } from '@/lib/audit/auditLogger'
import { sendMail } from '@/lib/email/acsMailer'
import { buildLeaveAppliedEmail } from '@/lib/email/templates/leaveApplied'
import { getNotificationEmail } from '@/lib/email/getNotificationEmail'

export async function POST(req: NextRequest) {
  try {
    const token = await validateToken(req)
    const body = await req.json()

    const {
      startDate,
      endDate,
      startDateType = 'full',
      endDateType = 'full',
      dayOverrides = [],
      totalDays,
      reason,
      isEmergency = false,
      managerId,
    } = body
    const title = typeof body.title === 'string' && body.title.trim() ? body.title.trim() : 'Leave Request'

    const normalizedStartHalfDay: any = startDateType === 'half' ? 'HALF_DAY' : 'NONE'
    const normalizedEndHalfDay: any = endDateType === 'half' ? 'HALF_DAY' : 'NONE'

    if (!startDate || !endDate || !reason) {
      return NextResponse.json({ error: 'Missing required fields', code: 'BAD_REQUEST' }, { status: 400 })
    }

    // Get existing leaves for overlap check
    const existingLeaves = await prisma.leaveRequest.findMany({
      where: {
        employeeId: token.userId,
        status: { in: ['PENDING', 'APPROVED'] },
      },
      select: { startDate: true, endDate: true, status: true },
    })

    const start = parseISO(startDate)
    const end = parseISO(endDate)

    // Validate dates
    const dateValidation = validateLeaveDates(startDate, endDate, existingLeaves.map((l) => ({
      startDate: l.startDate,
      endDate: l.endDate,
      status: l.status,
    })))

    if (!dateValidation.valid) {
      return NextResponse.json({ error: dateValidation.errors.join('; '), code: 'VALIDATION_ERROR' }, { status: 422 })
    }

    const holidaysForSandwich = await prisma.publicHoliday.findMany({ select: { date: true } })
    const sandwichCheck = validateSandwichRule(
      start,
      end,
      holidaysForSandwich.map((h) => ({ date: format(h.date, 'yyyy-MM-dd') }))
    )
    if (!sandwichCheck.valid) {
      return NextResponse.json(
        { error: sandwichCheck.error, code: 'SANDWICH_RULE' },
        { status: 422 }
      )
    }

    // Use totalDays from request
    let calculatedTotalDays = typeof totalDays === 'number' ? totalDays : 0
    if (calculatedTotalDays <= 0) {
      // Fallback calculation if not provided correctly
      calculatedTotalDays = computeTotalDays(start, end, normalizedStartHalfDay, normalizedEndHalfDay)
      const startStr = format(start, 'yyyy-MM-dd')
      const endStr = format(end, 'yyyy-MM-dd')
      const interiorHalfCount = dayOverrides.filter(
        (o: any) => o.date !== startStr && o.date !== endStr && !isWeekend(parseISO(o.date))
      ).length
      calculatedTotalDays = Math.max(0.5, calculatedTotalDays - interiorHalfCount * 0.5)
    }

    // Server-side validation: totalDays cannot exceed maximum possible working days in selected range
    if (typeof totalDays === 'number' && totalDays > 0) {
      const maxWorkingDays = computeTotalDays(start, end, normalizedStartHalfDay, normalizedEndHalfDay)
      if (totalDays > maxWorkingDays) {
        return NextResponse.json({ error: 'totalDays exceeds working days in selected range', code: 'VALIDATION_ERROR' }, { status: 400 })
      }
    }

    if (calculatedTotalDays <= 0) {
      return NextResponse.json({ error: 'Selected date range has no business days', code: 'VALIDATION_ERROR' }, { status: 422 })
    }

    // Emergency leave is not additional quota; it is a flagged leave
    // that must still come from standard balance and can be max 2 consecutive days.
    const balance = await getLeaveBalance(token.userId)
    const annual = balance.balances.find(b => b.type === 'ANNUAL')!
    const effectiveAvailable = annual.total - (annual.consumed + annual.inApproval)

    if (isEmergency) {
      if (calculatedTotalDays > 2) {
        return NextResponse.json(
          { error: 'Emergency leave can be applied for a maximum of 2 consecutive days.', code: 'VALIDATION_ERROR' },
          { status: 422 }
        )
      }
      const balanceValidation = validateBalance(calculatedTotalDays, effectiveAvailable)
      if (!balanceValidation.valid) {
        return NextResponse.json({ error: balanceValidation.errors.join('; '), code: 'INSUFFICIENT_BALANCE' }, { status: 422 })
      }
    } else {
      const balanceValidation = validateBalance(calculatedTotalDays, effectiveAvailable)
      if (!balanceValidation.valid) {
        return NextResponse.json({ error: balanceValidation.errors.join('; '), code: 'INSUFFICIENT_BALANCE' }, { status: 422 })
      }
    }

    // Fetch current employee to get their managerId
    const employeeData = await prisma.employee.findUnique({
      where: { id: token.userId },
      select: { managerId: true },
    })

    const resolvedManagerId = employeeData?.managerId || managerId || null

    if (!resolvedManagerId) {
      console.warn(`[/api/leave/apply] Employee ${token.userId} has no managerId set. Leave will be created but may not appear in any manager's approvals queue.`)
    }

    // Managers' own leave requests are auto-approved
    const isManagerApplying = token.role === 'MANAGER'
    const leaveStatus = isManagerApplying ? 'APPROVED' : 'PENDING'

    // Create leave request
    const leave = await prisma.leaveRequest.create({
      data: {
        employeeId: token.userId,
        managerId: resolvedManagerId,
        title,
        startDate: start,
        endDate: end,
        startHalfDay: normalizedStartHalfDay,
        endHalfDay: normalizedEndHalfDay,
        dayOverrides: Array.isArray(dayOverrides) ? dayOverrides : [],
        totalDays: calculatedTotalDays,
        reason: reason.trim(),
        isEmergency,
        status: leaveStatus,
        ...(isManagerApplying && {
          approverId: token.userId,
          approvedAt: new Date(),
        }),
        emailsSent: { applied: false },
      },
    })

    // Post-creation: notifications, emails, audit — failures here must NOT return 500
    // because the leave IS already created successfully.
    try {
    // Get employee's details for notification
    const employee = await prisma.employee.findUnique({
      where: { id: token.userId },
      select: {
        displayName: true,
        workEmail: true,
        notificationEmail: true,
        jobTitle: true,
        managerId: true,
        manager: { select: { workEmail: true, notificationEmail: true, displayName: true } }
      },
    })

    const hrEmployees = await prisma.employee.findMany({
      where: { role: { in: ['HR'] }, employmentStatus: 'ACTIVE' },
      select: { id: true, workEmail: true, notificationEmail: true, role: true },
    })

    const dateLabel = formatDateRange(startDate, endDate)
    const appBaseUrl = process.env.NEXTAUTH_URL ?? 'http://localhost:3000'

    // 1. Internal Notifications
    if (employee?.managerId) {
      await notifyLeaveApplied(
        token.userId,
        employee.displayName,
        employee.managerId,
        hrEmployees.map((h) => h.id),
        leave.id,
        dateLabel
      )
    } else {
      const allManagers = await prisma.employee.findMany({
        where: { role: 'MANAGER', employmentStatus: 'ACTIVE' },
        select: { id: true },
      })
      const recipientIds = Array.from(
        new Set([...allManagers.map((m) => m.id), ...hrEmployees.map((h) => h.id)])
      )
      await createNotifications(
        recipientIds.map((recipientId) => ({
          type: 'LEAVE_APPLIED' as const,
          title: 'New Leave Request',
          message: `${employee?.displayName ?? 'An employee'} has submitted a leave request for ${dateLabel}`,
          recipientId,
          senderId: token.userId,
          referenceId: leave.id,
        }))
      )
    }

    const fmtDate = (d: Date) => d.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' })

    // 2. Email Notifications
    const emailBase = {
      employeeName:  employee?.displayName ?? 'An employee',
      employeeEmail: employee ? getNotificationEmail(employee) : token.email,
      jobTitle:      employee?.jobTitle ?? null,
      startDate:     fmtDate(start),
      endDate:       fmtDate(end),
      totalDays,
      reason,
      isEmergency,
      leaveId:       leave.id,
      appBaseUrl,
    }

    // To Manager
    const managerAddress = employee?.manager ? getNotificationEmail(employee.manager) : null
    if (managerAddress) {
      const { subject, htmlBody } = buildLeaveAppliedEmail({
        ...emailBase,
        recipientRole: 'MANAGER',
      })
      await sendMail({ to: [managerAddress], subject, htmlBody }).catch(console.error)
    }

    // To HR/Admin
    for (const hr of hrEmployees) {
      const hrAddress = getNotificationEmail(hr)
      // Don't double-email if the manager is also HR/Admin
      if (hrAddress === managerAddress) continue

      const { subject, htmlBody } = buildLeaveAppliedEmail({
        ...emailBase,
        recipientRole: hr.role as 'HR',
      })
      await sendMail({ to: [hrAddress], subject, htmlBody }).catch(console.error)
    }

    await logAudit('LEAVE_APPLY', token.userId, token.userId, {
      before: {},
      after: { leaveId: leave.id, startDate, endDate, totalDays: calculatedTotalDays, isEmergency },
      params: { reason },
    }, req)
    } catch (postErr) {
      console.error('[/api/leave/apply] Post-creation side-effect error (leave WAS saved):', postErr)
    }

    return NextResponse.json({
      id: leave.id,
      message: 'Leave request submitted successfully',
    }, { status: 201 })
  } catch (err: unknown) {
    console.error('[/api/leave/apply] Error:', err)
    const message = err instanceof Error ? err.message : 'Unknown'
    if (message === 'UNAUTHORIZED') return NextResponse.json({ error: 'Unauthorized', code: 'UNAUTHORIZED' }, { status: 401 })
    return NextResponse.json({ error: 'Internal server error', code: 'INTERNAL_ERROR' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { validateToken } from '@/lib/auth/validateToken'
import { prisma } from '@/lib/db/prisma'
import { AuditAction } from '@prisma/client'

export async function PATCH(
  req: NextRequest,
  { params }: { params: { id: string } }
) {
  try {
    const token = await validateToken(req)
    const { id } = params
    const { status, rejectionReason } = await req.json()

    if (!status) {
      return NextResponse.json({ error: 'Missing status' }, { status: 400 })
    }

    const validTransitions: Record<string, string[]> = {
      PENDING: ['APPROVED', 'REJECTED', 'CANCELLED'],
      APPROVED: ['REVOKED', 'CANCELLED'],
      REJECTED: [],
      CANCELLED: [],
      REVOKED: []
    }

    const request = await prisma.leaveRequest.findUnique({
      where: { id },
    })

    if (!request) {
      return NextResponse.json({ error: 'Request not found' }, { status: 404 })
    }

    const allowed = validTransitions[request.status] || []
    if (!allowed.includes(status)) {
      return NextResponse.json({
        error: `Cannot transition from ${request.status} to ${status}`
      }, { status: 400 })
    }

    // Permission check
    if (status === 'CANCELLED') {
      if (request.employeeId !== token.userId) {
        return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
      }
    } else if (['APPROVED', 'REJECTED', 'REVOKED'].includes(status)) {
      if (!['MANAGER', 'HR'].includes(token.role)) {
        return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
      }
      // Manager check
      if (token.role === 'MANAGER' && request.managerId !== token.userId) {
        return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
      }
    }

    const updateData: any = { status }
    if (status === 'APPROVED') {
      updateData.approvedAt = new Date()
      updateData.approverId = token.userId
    } else if (status === 'REJECTED') {
      updateData.rejectedAt = new Date()
      updateData.approverId = token.userId
      updateData.rejectionReason = rejectionReason || null
    } else if (status === 'CANCELLED') {
      updateData.cancelledAt = new Date()
    } else if (status === 'REVOKED') {
      updateData.revokedAt = new Date()
      updateData.revokedBy = token.userId
      updateData.revocationReason = rejectionReason || null
    }

    const updated = await prisma.leaveRequest.update({
      where: { id },
      data: updateData,
    })

    // Write audit log
    const auditActionMap: Record<string, string> = {
      APPROVED: 'LEAVE_APPROVE',
      REJECTED: 'LEAVE_REJECT',
      CANCELLED: 'LEAVE_CANCEL',
      REVOKED: 'LEAVE_REVOKE'
    }

    await prisma.auditLog.create({
      data: {
        action: (auditActionMap[status] || 'LEAVE_APPROVE') as AuditAction,
        performedBy: token.userId,
        targetId: request.employeeId,
        details: { requestId: id, oldStatus: request.status, newStatus: status },
      }
    })

    return NextResponse.json({ success: true, data: updated })
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Unknown'
    if (message === 'UNAUTHORIZED') return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { validateToken } from '@/lib/auth/validateToken'
import { prisma } from '@/lib/db/prisma'

export async function GET(req: NextRequest) {
  try {
    const token = await validateToken(req)
    const url = new URL(req.url)
    const userIdParam = url.searchParams.get('userId')

    let targetUserId = token.userId

    // Allow HR/Admin/Manager to view other users' requests
    if (userIdParam && userIdParam !== token.userId) {
      if (!['HR', 'MANAGER'].includes(token.role)) {
        return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
      }
      
      if (token.role === 'MANAGER') {
        // Managers can only view their direct reports' requests
        const employee = await prisma.employee.findUnique({
          where: { id: userIdParam },
          select: { managerId: true },
        })
        if (!employee || employee.managerId !== token.userId) {
          return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
        }
      }
      
      targetUserId = userIdParam
    }

    const status = url.searchParams.get('status')

    const whereClause: any = { employeeId: targetUserId }
    if (status && status !== 'ALL') {
      whereClause.status = status
    }

    const leaves = await prisma.leaveRequest.findMany({
      where: whereClause,
      include: {
        approver: {
          select: { id: true, displayName: true, workEmail: true },
        },
        employee: {
          select: { id: true, displayName: true, workEmail: true },
        },
      },
      orderBy: { createdAt: 'desc' },
    })

    const data = leaves.map((l) => ({
      ...l,
      approver: l.approver ? { ...l.approver, email: (l.approver as any).workEmail } : null,
      employee: l.employee ? { ...l.employee, email: (l.employee as any).workEmail } : null,
      startDate: l.startDate.toISOString(),
      endDate: l.endDate.toISOString(),
      approvedAt: l.approvedAt?.toISOString() ?? null,
      rejectedAt: l.rejectedAt?.toISOString() ?? null,
      revokedAt: l.revokedAt?.toISOString() ?? null,
      cancelledAt: l.cancelledAt?.toISOString() ?? null,
      createdAt: l.createdAt.toISOString(),
      updatedAt: l.updatedAt.toISOString(),
    }))

    return NextResponse.json({ data, total: data.length })
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Unknown'
    if (message === 'UNAUTHORIZED') return NextResponse.json({ error: 'Unauthorized', code: 'UNAUTHORIZED' }, { status: 401 })
    return NextResponse.json({ error: 'Internal server error', code: 'INTERNAL_ERROR' }, { status: 500 })
  }
}

export async function PATCH(req: NextRequest) {
  try {
    const token = await validateToken(req)
    const body = await req.json()
    const { id, status, rejectionReason } = body

    if (!id || !status) {
      return NextResponse.json({ error: 'Missing required fields', code: 'BAD_REQUEST' }, { status: 400 })
    }

    // Validate status
    const validStatuses = ['APPROVED', 'REJECTED', 'CANCELLED', 'REVOKED']
    if (!validStatuses.includes(status)) {
      return NextResponse.json({ error: 'Invalid status', code: 'BAD_REQUEST' }, { status: 400 })
    }

    // Check permissions
    const leave = await prisma.leaveRequest.findUnique({
      where: { id },
      include: {
        employee: { select: { managerId: true } },
      },
    })

    if (!leave) {
      return NextResponse.json({ error: 'Leave request not found', code: 'NOT_FOUND' }, { status: 404 })
    }

    // Only approvers can approve/reject
    if (['APPROVED', 'REJECTED'].includes(status)) {
      if (!['HR', 'MANAGER'].includes(token.role)) {
        return NextResponse.json({ error: 'Forbidden', code: 'FORBIDDEN' }, { status: 403 })
      }
      
      if (token.role === 'MANAGER' && leave.employee?.managerId !== token.userId) {
        return NextResponse.json({ error: 'Forbidden', code: 'FORBIDDEN' }, { status: 403 })
      }
    }

    // Only employee can cancel their own request
    if (status === 'CANCELLED' && leave.employeeId !== token.userId) {
      return NextResponse.json({ error: 'Forbidden', code: 'FORBIDDEN' }, { status: 403 })
    }

    // Update the leave request
    const updateData: any = {
      status,
      approverId: ['APPROVED', 'REJECTED'].includes(status) ? token.userId : leave.approverId,
    }

    if (status === 'APPROVED') {
      updateData.approvedAt = new Date()
    } else if (status === 'REJECTED') {
      updateData.rejectedAt = new Date()
      updateData.rejectionReason = rejectionReason || null
    } else if (status === 'CANCELLED') {
      updateData.cancelledAt = new Date()
    } else if (status === 'REVOKED') {
      updateData.revokedAt = new Date()
      updateData.revokedBy = token.userId
      updateData.revocationReason = rejectionReason || null
    }

    const updatedLeave = await prisma.leaveRequest.update({
      where: { id },
      data: updateData,
      include: {
        approver: {
          select: { id: true, displayName: true, workEmail: true },
        },
        employee: {
          select: { id: true, displayName: true, workEmail: true },
        },
      },
    })

    // Write audit log
    const auditActionMap: Record<string, any> = {
      APPROVED: 'LEAVE_APPROVE',
      REJECTED: 'LEAVE_REJECT',
      CANCELLED: 'LEAVE_CANCEL',
      REVOKED: 'LEAVE_REVOKE'
    }

    try {
      const { logAudit } = await import('@/lib/audit/auditLogger')
      await logAudit(
        auditActionMap[status] || 'LEAVE_APPROVE',
        token.userId,
        leave.employeeId,
        { requestId: id, oldStatus: leave.status, newStatus: status },
        req
      )
    } catch (auditErr) {
      console.error('[Audit] Failed to log leave status change:', auditErr)
    }

    return NextResponse.json({
      ...updatedLeave,
      approver: updatedLeave.approver ? { ...updatedLeave.approver, email: (updatedLeave.approver as any).workEmail } : null,
      employee: updatedLeave.employee ? { ...updatedLeave.employee, email: (updatedLeave.employee as any).workEmail } : null,
      startDate: updatedLeave.startDate.toISOString(),
      endDate: updatedLeave.endDate.toISOString(),
      approvedAt: updatedLeave.approvedAt?.toISOString() ?? null,
      rejectedAt: updatedLeave.rejectedAt?.toISOString() ?? null,
      revokedAt: updatedLeave.revokedAt?.toISOString() ?? null,
      cancelledAt: updatedLeave.cancelledAt?.toISOString() ?? null,
      createdAt: updatedLeave.createdAt.toISOString(),
      updatedAt: updatedLeave.updatedAt.toISOString(),
    })
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Unknown'
    if (message === 'UNAUTHORIZED') return NextResponse.json({ error: 'Unauthorized', code: 'UNAUTHORIZED' }, { status: 401 })
    return NextResponse.json({ error: 'Internal server error', code: 'INTERNAL_ERROR' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { validateToken, requireRole } from '@/lib/auth/validateToken'
import { prisma } from '@/lib/db/prisma'
import { logAudit } from '@/lib/audit/auditLogger'
import { countBusinessDays, formatDateRange } from '@/lib/utils/dateUtils'
import { format, parseISO } from 'date-fns'
import { validateSandwichRule } from '@/lib/leave/leaveValidator'
import { createNotifications } from '@/lib/notifications/notificationService'
import { sendMail } from '@/lib/email/acsMailer'
import { buildManagerOnLeaveEmail } from '@/lib/email/templates/managerOnLeave'
import { getNotificationEmail } from '@/lib/email/getNotificationEmail'

export async function POST(req: NextRequest) {
  try {
    const token = await validateToken(req)
    requireRole(token, ['MANAGER'])

    const body = await req.json()
    const { title, startDate, endDate, startHalfDay = 'NONE', endHalfDay = 'NONE', halfDayDates = [], dayOverrides = [], totalDays, reason, isEmergency = false } = body

    const normalizedStartHalfDay = startHalfDay === 'NONE' ? 'NONE' : 'HALF_DAY'
    const normalizedEndHalfDay = endHalfDay === 'NONE' ? 'NONE' : 'HALF_DAY'

    if (!title || !startDate || !endDate || !reason) {
      return NextResponse.json({ error: 'title, startDate, endDate, and reason are required' }, { status: 400 })
    }

    const start = parseISO(startDate)
    const end = parseISO(endDate)
    const today = new Date()
    today.setHours(0, 0, 0, 0)

    if (start < today) {
      return NextResponse.json({ error: 'Leave cannot start in the past' }, { status: 400 })
    }

    // Check for overlapping leaves
    const overlap = await prisma.leaveRequest.findFirst({
      where: {
        employeeId: token.userId,
        status: { in: ['PENDING', 'APPROVED'] },
        startDate: { lte: end },
        endDate: { gte: start },
      },
    })

    if (overlap) {
      return NextResponse.json({ error: 'You already have a leave in this period' }, { status: 409 })
    }

    const holidaysForSandwich = await prisma.publicHoliday.findMany({ select: { date: true } })
    const sandwichCheck = validateSandwichRule(
      start,
      end,
      holidaysForSandwich.map((h) => ({ date: format(h.date, 'yyyy-MM-dd') }))
    )
    if (!sandwichCheck.valid) {
      return NextResponse.json({ error: sandwichCheck.error, code: 'SANDWICH_RULE' }, { status: 422 })
    }

    // Fetch public holidays in range
    const publicHolidays = await prisma.publicHoliday.findMany({
      where: { date: { gte: start, lte: end } },
    })
    const holidayDates = publicHolidays.map((h) => h.date.toDateString())

    // Use totalDays from request if provided, otherwise compute it
    let calculatedTotalDays = totalDays
    if (typeof totalDays !== 'number' || totalDays <= 0) {
      // Fallback to original calculation for backward compatibility
      calculatedTotalDays = countBusinessDays(start, end, holidayDates)
      // Apply half-day adjustments
      if (normalizedStartHalfDay !== 'NONE') calculatedTotalDays -= 0.5
      if (normalizedEndHalfDay !== 'NONE' && end.toDateString() !== start.toDateString()) calculatedTotalDays -= 0.5
      calculatedTotalDays = Math.max(0.5, calculatedTotalDays)
    }

    // Check balance
    const balance = await prisma.leaveBalance.findUnique({ where: { employeeId: token.userId } })
    if (!balance) return NextResponse.json({ error: 'No leave balance found' }, { status: 400 })

    if (isEmergency) {
      if (calculatedTotalDays > 2) {
        return NextResponse.json(
          { error: 'Emergency leave can be applied for a maximum of 2 consecutive days.' },
          { status: 400 }
        )
      }
      const availableStandard = balance.standardTotal + balance.standardCarryForward - balance.standardUsed
      if (calculatedTotalDays > availableStandard) {
        return NextResponse.json({ error: `Insufficient balance. You have ${availableStandard} days remaining.` }, { status: 400 })
      }
    } else {
      const availableStandard = balance.standardTotal + balance.standardCarryForward - balance.standardUsed
      if (calculatedTotalDays > availableStandard) {
        return NextResponse.json({ error: `Insufficient balance. You have ${availableStandard} days remaining.` }, { status: 400 })
      }
    }

    const now = new Date()

    // Create leave request as APPROVED (manager self-approves)
    const leave = await prisma.leaveRequest.create({
      data: {
        employeeId: token.userId,
        title,
        startDate: start,
        endDate: end,
        startHalfDay: normalizedStartHalfDay,
        endHalfDay: normalizedEndHalfDay,
        halfDayDates: Array.isArray(halfDayDates) ? halfDayDates : [],
        dayOverrides: Array.isArray(dayOverrides) ? dayOverrides : [],
        totalDays: calculatedTotalDays,
        reason,
        isEmergency,
        status: 'APPROVED',
        approverId: token.userId,
        approvedAt: now,
      },
    })

    // Fetch manager's profile + all recipients (Direct Reports + HR/Admin)
    const [managerProfile, emailRecipients] = await Promise.all([
      prisma.employee.findUnique({
        where: { id: token.userId },
        select: { displayName: true, workEmail: true, notificationEmail: true, jobTitle: true },
      }),
      prisma.employee.findMany({
        where: {
          employmentStatus: 'ACTIVE',
          OR: [
            { managerId: token.userId },           // direct reports
            { role: { in: ['HR'] } },    // HR and Admin
          ],
        },
        select: { id: true, workEmail: true, notificationEmail: true, role: true },
      }),
    ])

    const dateLabel = formatDateRange(startDate, endDate)
    const appBaseUrl = process.env.NEXTAUTH_URL ?? 'http://localhost:3000'

    // 1. Email Notifications
    const recipientEmails = Array.from(new Set(
      emailRecipients
        .map(r => getNotificationEmail(r))
        .filter(e => e !== getNotificationEmail(managerProfile as any))
    ))

    if (recipientEmails.length > 0) {
      const fmtDate = (d: Date) => d.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' })
      const { subject, htmlBody } = buildManagerOnLeaveEmail({
        managerName: managerProfile?.displayName ?? 'Your manager',
        jobTitle:    managerProfile?.jobTitle    ?? null,
        startDate:   fmtDate(start),
        endDate:     fmtDate(end),
        totalDays:   leave.totalDays,
        appBaseUrl,
      })
      await sendMail({ to: recipientEmails, subject, htmlBody }).catch(console.error)
    }

    // 2. In-app Notifications
    if (emailRecipients.length > 0) {
      await createNotifications(
        emailRecipients.map((recipient) => ({
          type: 'LEAVE_APPLIED',
          title: 'Manager Leave Notice',
          message: `${managerProfile?.displayName ?? 'A manager'} is on leave for ${dateLabel} (auto-approved).`,
          recipientId: recipient.id,
          senderId: token.userId,
          referenceId: leave.id,
        }))
      )
    }

    // Create ledger entry
    await prisma.leaveLedgerEntry.create({
      data: {
        employeeId: token.userId,
        type: 'USAGE',
        days: calculatedTotalDays,
        reason: `Manager self-approved leave: ${title}`,
        referenceId: leave.id,
        performedBy: token.userId,
        year: now.getFullYear(),
      },
    })

    // Update balance
    await prisma.leaveBalance.update({
      where: { employeeId: token.userId },
      data: { standardUsed: { increment: calculatedTotalDays } },
    })

    await logAudit('LEAVE_APPROVE', token.userId, token.userId, {
      before: {},
      after: { leaveId: leave.id, totalDays: calculatedTotalDays, selfApproved: true, note: 'self-approved by manager' },
      params: {},
    }, req)

    return NextResponse.json(leave, { status: 201 })
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Unknown'
    if (message === 'UNAUTHORIZED') return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    if (message === 'FORBIDDEN') return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { validateToken, requireRole } from '@/lib/auth/validateToken'
import { prisma } from '@/lib/db/prisma'
import { postUsage } from '@/lib/leave/ledgerService'
import { formatDateRange } from '@/lib/utils/dateUtils'
import { sendMail } from '@/lib/email/acsMailer'
import { buildLeaveStatusUpdateEmail } from '@/lib/email/templates/leaveStatusUpdate'
import { buildLeaveApprovedBroadcastEmail } from '@/lib/email/templates/leaveApprovedBroadcast'
import { getNotificationEmail } from '@/lib/email/getNotificationEmail'
import { notifyLeaveApproved, notifyLeaveRejected } from '@/lib/notifications/notificationService'
import { logAudit } from '@/lib/audit/auditLogger'

export async function PATCH(
  req: NextRequest,
  { params }: { params: { id: string } }
) {
  try {
    const token = await validateToken(req)
    requireRole(token, ['MANAGER', 'HR'])

    const { id } = params
    const body = await req.json()
    const { action, reason } = body

    if (!['approve', 'reject'].includes(action)) {
      return NextResponse.json({ error: 'Invalid action', code: 'BAD_REQUEST' }, { status: 400 })
    }

    const leave = await prisma.leaveRequest.findUnique({
      where: { id },
      include: {
        employee: { select: { id: true, displayName: true, workEmail: true, notificationEmail: true, managerId: true } },
      },
    })

    if (!leave) {
      return NextResponse.json({ error: 'Leave not found', code: 'NOT_FOUND' }, { status: 404 })
    }

    if (leave.status !== 'PENDING') {
      return NextResponse.json({ error: 'Leave is no longer pending', code: 'INVALID_STATUS' }, { status: 422 })
    }

    const dates = formatDateRange(leave.startDate.toISOString(), leave.endDate.toISOString())

    if (action === 'approve') {
      await prisma.leaveRequest.update({
        where: { id },
        data: {
          status: 'APPROVED',
          approverId: token.userId,
          approvedAt: new Date(),
          approverComments: reason || null,
        },
      })

      // Deduct balance via ledger
      await postUsage({
        employeeId: leave.employeeId,
        days: leave.totalDays,
        reason: `Leave approved by ${token.email}`,
        referenceId: id,
        performedBy: token.userId,
        year: leave.startDate.getFullYear(),
        month: leave.startDate.getMonth() + 1,
      })

      await notifyLeaveApproved(leave.employeeId, token.userId, id, dates)

      // 3. Send emails
      const appBaseUrl = process.env.NEXTAUTH_URL ?? 'http://localhost:3000'

      // Fetch additional data for emails
      const [approverProfile, broadcastRecipients] = await Promise.all([
        prisma.employee.findUnique({
          where: { id: token.userId },
          select: { displayName: true },
        }),
        // Broadcast: all team members (managerId === approver) + all HR + Admin
        prisma.employee.findMany({
          where: {
            employmentStatus: 'ACTIVE',
            OR: [
              { managerId: token.userId },
              { role: { in: ['HR'] } }
            ]
          },
          select: { workEmail: true, notificationEmail: true, role: true, displayName: true, jobTitle: true }
        })
      ])

      const employeeRef = leave.employee
      const employeeAddress = getNotificationEmail(employeeRef)

      // A. Personal confirmation to employee
      const { subject: empSub, htmlBody: empBody } = buildLeaveStatusUpdateEmail({
        employeeName:    employeeRef.displayName,
        startDate:       leave.startDate,
        endDate:         leave.endDate,
        totalDays:       leave.totalDays,
        status:          'APPROVED',
        reason:          leave.reason,
        approverComment: reason || null,
        appBaseUrl,
        leaveId:         id,
        recipientRole:   'EMPLOYEE',
      })
      await sendMail({ to: [employeeAddress], subject: empSub, htmlBody: empBody }).catch(console.error)

      // B. Broadcast to team + HR + Admin
      const fmtDate = (d: Date) => d.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' })
      const startStr = fmtDate(leave.startDate)
      const endStr   = fmtDate(leave.endDate)

      for (const recipient of broadcastRecipients) {
        const recipientAddress = getNotificationEmail(recipient)
        if (recipientAddress === employeeAddress) continue // skip self

        const { subject, htmlBody } = buildLeaveApprovedBroadcastEmail({
          employeeName: employeeRef.displayName,
          jobTitle:     (employeeRef as any).jobTitle ?? null,
          startDate:    startStr,
          endDate:      endStr,
          totalDays:    leave.totalDays,
          approverName: approverProfile?.displayName ?? 'Manager',
          appBaseUrl,
          recipientRole: recipient.role as any,
        })
        await sendMail({ to: [recipientAddress], subject, htmlBody }).catch(console.error)
      }

      await logAudit('LEAVE_APPROVE', token.userId, leave.employeeId, {
        before: { status: 'PENDING' },
        after: { status: 'APPROVED' },
        params: { leaveId: id },
      }, req)

    } else {
      if (!reason) {
        return NextResponse.json({ error: 'Rejection reason is required', code: 'VALIDATION_ERROR' }, { status: 422 })
      }

      await prisma.leaveRequest.update({
        where: { id },
        data: {
          status: 'REJECTED',
          approverId: token.userId,
          rejectedAt: new Date(),
          rejectionReason: reason,
        },
      })

      await notifyLeaveRejected(leave.employeeId, token.userId, id, dates)

      // Send email
      const employeeRef = leave.employee
      const employeeAddress = getNotificationEmail(employeeRef)
      const appBaseUrl = process.env.NEXTAUTH_URL ?? 'http://localhost:3000'

      const { subject: rejSubject, htmlBody: rejBody } = buildLeaveStatusUpdateEmail({
        employeeName:    employeeRef.displayName,
        startDate:       leave.startDate,
        endDate:         leave.endDate,
        totalDays:       leave.totalDays,
        status:          'REJECTED',
        reason:          leave.reason,
        approverComment: reason,
        appBaseUrl,
        leaveId:         id,
        recipientRole:   'EMPLOYEE',
      })
      await sendMail({ to: [employeeAddress], subject: rejSubject, htmlBody: rejBody }).catch(console.error)
      await logAudit('LEAVE_REJECT', token.userId, leave.employeeId, {
        before: { status: 'PENDING' },
        after: { status: 'REJECTED' },
        params: { leaveId: id, reason },
      }, req)
    }

    return NextResponse.json({ message: `Leave ${action}d successfully` })
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Unknown'
    if (message === 'UNAUTHORIZED') return NextResponse.json({ error: 'Unauthorized', code: 'UNAUTHORIZED' }, { status: 401 })
    if (message === 'FORBIDDEN') return NextResponse.json({ error: 'Forbidden', code: 'FORBIDDEN' }, { status: 403 })
    console.error('[/api/manager/approvals/[id]] Error:', err)
    return NextResponse.json({ error: 'Internal server error', code: 'INTERNAL_ERROR' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { validateToken, requireRole } from '@/lib/auth/validateToken'
import { prisma } from '@/lib/db/prisma'

export async function GET(req: NextRequest) {
  try {
    const token = await validateToken(req)
    requireRole(token, ['MANAGER', 'HR'])

    // Find team members (employees whose manager is the current user)
    const teamMembers = await prisma.employee.findMany({
      where: { managerId: token.userId, employmentStatus: 'ACTIVE' },
      select: { id: true },
    })

    const teamIds = teamMembers.map((m) => m.id)

    const useAllEmployees = token.role === 'HR'

    const url = new URL(req.url)
    const status = url.searchParams.get('status')

    const approvals = await prisma.leaveRequest.findMany({
      where: {
        ...(useAllEmployees
          ? {}
          : {
              OR: [
                { managerId: token.userId },
                { employeeId: { in: teamIds }, managerId: null },
              ],
            }),
        ...(status && status !== 'ALL' ? { status: status as any } : { status: 'PENDING' }),
      },
      include: {
        employee: {
          select: {
            id: true,
            displayName: true,
            workEmail: true,
            jobTitle: true,
            profilePictureUrl: true,
          },
        },
      },
      orderBy: { createdAt: 'desc' },
    })

    return NextResponse.json(
      approvals.map((a) => ({
        ...a,
        startDate: a.startDate.toISOString(),
        endDate: a.endDate.toISOString(),
        approvedAt: a.approvedAt?.toISOString() ?? null,
        rejectedAt: a.rejectedAt?.toISOString() ?? null,
        createdAt: a.createdAt.toISOString(),
        updatedAt: a.updatedAt.toISOString(),
      }))
    )
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Unknown'
    if (message === 'UNAUTHORIZED') return NextResponse.json({ error: 'Unauthorized', code: 'UNAUTHORIZED' }, { status: 401 })
    if (message === 'FORBIDDEN') return NextResponse.json({ error: 'Forbidden', code: 'FORBIDDEN' }, { status: 403 })
    return NextResponse.json({ error: 'Internal server error', code: 'INTERNAL_ERROR' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { validateToken, requireRole } from '@/lib/auth/validateToken'
import { prisma } from '@/lib/db/prisma'

export async function GET(
  req: NextRequest,
  { params }: { params: { id: string } }
) {
  try {
    const token = await validateToken(req)
    requireRole(token, ['MANAGER', 'HR'])

    const employee = await prisma.employee.findUnique({
      where: { id: params.id },
      include: {
        manager: { select: { id: true, displayName: true, workEmail: true } },
        leaveBalance: true,
        leaveRequests: {
          orderBy: { createdAt: 'desc' },
          take: 20,
          include: {
            approver: { select: { id: true, displayName: true, workEmail: true } },
          },
        },
      },
    })

    if (!employee) {
      return NextResponse.json({ error: 'Employee not found' }, { status: 404 })
    }

    const result = {
      id: employee.id,
      entraObjectId: employee.entraObjectId,
      email: employee.workEmail,
      workEmail: employee.workEmail,
      notificationEmail: employee.notificationEmail,
      displayName: employee.displayName,
      firstName: employee.firstName,
      lastName: employee.lastName,
      jobTitle: employee.jobTitle,
      phoneNumber: employee.phoneNumber,
      emergencyName: employee.emergencyName,
      emergencyRelation: employee.emergencyRelation,
      emergencyPhone: employee.emergencyPhone,
      profilePictureUrl: employee.profilePictureUrl,
      role: employee.role,
      employmentStatus: employee.employmentStatus,
      managerId: employee.managerId,
      manager: employee.manager,
      joinDate: employee.joinDate.toISOString(),
      terminationDate: employee.terminationDate?.toISOString() ?? null,
      createdAt: employee.createdAt.toISOString(),
      updatedAt: employee.updatedAt.toISOString(),
      leaveBalance: employee.leaveBalance
        ? {
            year: employee.leaveBalance.year,
            standardTotal: employee.leaveBalance.standardTotal,
            standardUsed: employee.leaveBalance.standardUsed,
            standardCarryForward: employee.leaveBalance.standardCarryForward,
            availableStandard:
              employee.leaveBalance.standardTotal +
              employee.leaveBalance.standardCarryForward -
              employee.leaveBalance.standardUsed,
            emergencyTotal: employee.leaveBalance.emergencyTotal,
            emergencyUsed: employee.leaveBalance.emergencyUsed,
            availableEmergency: employee.leaveBalance.emergencyTotal - employee.leaveBalance.emergencyUsed,
          }
        : null,
      leaveRequests: employee.leaveRequests.map((lr) => ({
        id: lr.id,
        title: lr.title,
        startDate: lr.startDate.toISOString(),
        endDate: lr.endDate.toISOString(),
        totalDays: lr.totalDays,
        reason: lr.reason,
        status: lr.status,
        isEmergency: lr.isEmergency,
        approver: lr.approver ? { ...lr.approver, email: (lr.approver as any).workEmail } : null,
        rejectionReason: lr.rejectionReason,
        createdAt: lr.createdAt.toISOString(),
      })),
    }

    return NextResponse.json(result)
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Unknown'
    if (message === 'UNAUTHORIZED') return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    if (message === 'FORBIDDEN') return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

