'use client'

import { useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { X, Download, Loader2, FileSpreadsheet, FileText, File } from 'lucide-react'
import { useMsal } from '@azure/msal-react'
import toast from 'react-hot-toast'
import { getAccessToken } from '@/lib/auth/getAccessToken'

interface ExportEmployeesModalProps {
  isOpen: boolean
  onClose: () => void
  totalCount: number
}

type ExportFormat = 'xlsx' | 'csv' | 'pdf'

const FORMAT_OPTIONS: { format: ExportFormat; label: string; description: string; icon: React.ReactNode; ext: string }[] = [
  {
    format: 'xlsx',
    label: 'Excel',
    description: 'Best for filtering, sorting, and editing data',
    icon: <FileSpreadsheet size={24} className="text-green-600" />,
    ext: '.xlsx',
  },
  {
    format: 'csv',
    label: 'CSV',
    description: 'Universal format compatible with all spreadsheet apps',
    icon: <FileText size={24} className="text-blue-600" />,
    ext: '.csv',
  },
  {
    format: 'pdf',
    label: 'PDF',
    description: 'Opens a printable view — use browser Print → Save as PDF',
    icon: <File size={24} className="text-red-500" />,
    ext: '.pdf',
  },
]

export function ExportEmployeesModal({ isOpen, onClose, totalCount }: ExportEmployeesModalProps) {
  const { instance } = useMsal()
  const [selected, setSelected] = useState<ExportFormat>('xlsx')
  const [isDownloading, setIsDownloading] = useState(false)

  const handleDownload = async () => {
    setIsDownloading(true)
    try {
      const token = await getAccessToken(instance)
      const res = await fetch(`/api/hr/employees/export?format=${selected}`, {
        headers: { Authorization: `Bearer ${token}` },
      })
      if (!res.ok) throw new Error('Export failed. Please try again.')

      if (selected === 'pdf') {
        // Open HTML in new tab for browser print-to-PDF
        const html = await res.text()
        const blob = new Blob([html], { type: 'text/html' })
        const url = URL.createObjectURL(blob)
        window.open(url, '_blank')
        setTimeout(() => URL.revokeObjectURL(url), 10000)
        toast.success('PDF view opened — use Print → Save as PDF')
      } else {
        const blob = await res.blob()
        const url = URL.createObjectURL(blob)
        const filename = `employees_${new Date().toISOString().split('T')[0]}`
        const downloadLink = document.createElement('a')
        downloadLink.href = url
        downloadLink.download = `${filename}.${selected}`
        document.body.appendChild(downloadLink)
        downloadLink.click()
        URL.revokeObjectURL(url)
        document.body.removeChild(downloadLink)
        toast.success(`Downloaded ${filename}.${selected}`)
      }
      onClose()
    } catch (err: any) {
      toast.error(err.message ?? 'Export failed')
    } finally {
      setIsDownloading(false)
    }
  }

  return (
    <AnimatePresence>
      {isOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <motion.div
            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
            className="absolute inset-0 bg-black/40 backdrop-blur-sm"
            onClick={onClose}
          />
          <motion.div
            initial={{ scale: 0.95, opacity: 0, y: 16 }}
            animate={{ scale: 1, opacity: 1, y: 0 }}
            exit={{ scale: 0.95, opacity: 0, y: 16 }}
            className="relative bg-white rounded-2xl shadow-2xl w-full max-w-md"
          >
            {/* Header */}
            <div className="p-6 border-b border-slate-100 flex items-center justify-between">
              <div>
                <h3 className="text-xl font-bold text-slate-900 flex items-center gap-2">
                  <Download size={20} className="text-blue-600" /> Download Employee Data
                </h3>
                <p className="text-slate-500 text-sm mt-0.5">{totalCount} employees · all active & inactive</p>
              </div>
              <button onClick={onClose}
                className="p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-full transition-all">
                <X size={20} />
              </button>
            </div>

            {/* Format selector */}
            <div className="p-6 space-y-3">
              <p className="text-xs font-semibold text-slate-500 uppercase tracking-widest mb-4">Select Format</p>
              {FORMAT_OPTIONS.map(opt => (
                <button
                  key={opt.format}
                  onClick={() => setSelected(opt.format)}
                  className={`w-full flex items-center gap-4 p-4 rounded-xl border-2 transition-all text-left ${
                    selected === opt.format
                      ? 'border-blue-500 bg-blue-50'
                      : 'border-slate-200 hover:border-slate-300 hover:bg-slate-50'
                  }`}
                >
                  <div className="flex-shrink-0">{opt.icon}</div>
                  <div>
                    <p className={`font-semibold text-sm ${selected === opt.format ? 'text-blue-700' : 'text-slate-900'}`}>
                      {opt.label} <span className="font-normal text-slate-400 font-mono text-xs">{opt.ext}</span>
                    </p>
                    <p className="text-xs text-slate-500 mt-0.5">{opt.description}</p>
                  </div>
                  <div className="ml-auto flex-shrink-0">
                    <div className={`w-4 h-4 rounded-full border-2 flex items-center justify-center ${
                      selected === opt.format ? 'border-slate-800 bg-slate-800' : 'border-slate-300'
                    }`}>
                      {selected === opt.format && <div className="w-1.5 h-1.5 rounded-full bg-white" />}
                    </div>
                  </div>
                </button>
              ))}
            </div>

            {/* Footer */}
            <div className="p-6 border-t border-slate-100 bg-slate-50 rounded-b-2xl flex justify-between">
              <button onClick={onClose} className="btn-secondary" disabled={isDownloading}>Cancel</button>
              <button
                onClick={handleDownload}
                disabled={isDownloading}
                className="btn-primary flex items-center gap-2 min-w-[140px] justify-center"
              >
                {isDownloading
                  ? <><Loader2 className="animate-spin" size={16} /> Preparing...</>
                  : <><Download size={16} /> Download {selected.toUpperCase()}</>
                }
              </button>
            </div>
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  )
}

'use client'

import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { useMsal } from '@azure/msal-react'
import { getAccessToken } from '@/lib/auth/getAccessToken'
import { format, parseISO } from 'date-fns'
import { Trash2, Upload, Pencil, FileText, CheckCircle2 } from 'lucide-react'
import { motion } from 'framer-motion'
import toast from 'react-hot-toast'
import * as XLSX from 'xlsx'
import { cn } from '@/lib/utils/cn'

interface PublicHoliday {
  id: string
  name: string
  date: string
  type: 'PUBLIC' | 'FLOATER'
  notes?: string | null
}

export function HolidayManagerTab() {
  const { instance } = useMsal()
  const queryClient = useQueryClient()
  const [view, setView] = useState<'upload' | 'records'>('upload')
  const [editingId, setEditingId] = useState<string | null>(null)
  const [editForm, setEditForm] = useState({ name: '', date: '', type: 'PUBLIC' as 'PUBLIC' | 'FLOATER', notes: '' })

  const { data: holidays = [], isLoading } = useQuery<PublicHoliday[]>({
    queryKey: ['publicHolidays'],
    queryFn: async () => {
      const token = await getAccessToken(instance)
      const res = await fetch('/api/holidays', { headers: { Authorization: `Bearer ${token}` } })
      if (!res.ok) return []
      return res.json()
    },
  })

  const updateMutation = useMutation({
    mutationFn: async (data: { id: string; name: string; date: string; type: string; notes: string }) => {
      const token = await getAccessToken(instance)
      const res = await fetch(`/api/holidays/${data.id}`, {
        method: 'PATCH',
        headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
        body: JSON.stringify(data),
      })
      if (!res.ok) throw new Error('Update failed')
      return res.json()
    },
    onSuccess: () => {
      toast.success('Holiday updated')
      queryClient.invalidateQueries({ queryKey: ['publicHolidays'] })
      setEditingId(null)
    },
    onError: (err: Error) => toast.error(err.message),
  })

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      const token = await getAccessToken(instance)
      const res = await fetch(`/api/holidays/${id}`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${token}` },
      })
      if (!res.ok) throw new Error('Failed to delete')
    },
    onSuccess: () => {
      toast.success('Holiday removed')
      queryClient.invalidateQueries({ queryKey: ['publicHolidays'] })
    },
    onError: (err: Error) => toast.error(err.message),
  })

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-xl font-bold text-slate-900">Public Holidays</h2>
          <p className="text-[13px] font-medium text-slate-500 mt-0.5">Manage the annual holiday calendar for all employees.</p>
        </div>

        <div className="inline-flex bg-slate-100/80 p-1 rounded-xl border border-slate-200 shadow-inner">
          <button 
            onClick={() => setView('upload')}
            className={cn(
              "px-4 py-1.5 rounded-lg text-[11px] font-bold uppercase tracking-widest transition-all",
              view === 'upload' 
                ? "bg-white text-blue-600 shadow-sm border border-slate-100" 
                : "text-slate-500 hover:text-slate-700"
            )}
          >
            Bulk Upload
          </button>
          <button 
            onClick={() => setView('records')}
            className={cn(
              "px-4 py-1.5 rounded-lg text-[11px] font-bold uppercase tracking-widest transition-all",
              view === 'records' 
                ? "bg-white text-blue-600 shadow-sm border border-slate-100" 
                : "text-slate-500 hover:text-slate-700"
            )}
          >
            View Directory
          </button>
        </div>
      </div>

      <motion.div 
        key={view}
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.2 }}
      >
        {view === 'upload' ? <HolidayUploadView /> : <HolidayRecordsView 
          holidays={holidays} 
          isLoading={isLoading} 
          onDelete={(id: string) => deleteMutation.mutate(id)}
          isDeleting={deleteMutation.isPending}
          editingId={editingId}
          setEditingId={setEditingId}
          editForm={editForm}
          setEditForm={setEditForm}
          onUpdate={(data: any) => updateMutation.mutate(data)}
          isUpdating={updateMutation.isPending}
        />}
      </motion.div>
    </div>
  )
}

function HolidayUploadView() {
  const { instance } = useMsal()
  const queryClient = useQueryClient()
  const [parsed, setParsed] = useState<any[]>([])
  const [fileName, setFileName] = useState('')

  const uploadMutation = useMutation({
    mutationFn: async (data: any[]) => {
      const token = await getAccessToken(instance)
      const res = await fetch('/api/hr/holidays/upload', {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
        body: JSON.stringify(data),
      })
      if (!res.ok) throw new Error('Upload failed')
      return res.json()
    },
    onSuccess: (data) => {
      toast.success(`${data.processed} holidays imported successfully`)
      queryClient.invalidateQueries({ queryKey: ['publicHolidays'] })
      setParsed([])
      setFileName('')
    },
    onError: (err: Error) => toast.error(err.message),
  })

  const handleFile = async (file: File) => {
    const ext = file.name.split('.').pop()?.toLowerCase()
    setFileName(file.name)

    if (ext === 'csv') {
      const text = await file.text()
      const lines = text.trim().split('\n')
      const headers = lines[0].split(',').map(h => h.trim().toLowerCase())
      const rows = lines.slice(1).map(line => {
        const vals = line.split(',').map(v => v.trim())
        const row: any = {}
        headers.forEach((h, i) => { row[h] = vals[i] })
        return { name: row.name, date: row.date, type: row.type, notes: row.notes }
      })
      setParsed(rows.filter(r => r.name && r.date))
    } else if (ext === 'xlsx' || ext === 'xls') {
      const buffer = await file.arrayBuffer()
      const wb = XLSX.read(buffer, { type: 'array' })
      const ws = wb.Sheets[wb.SheetNames[0]]
      const rows: any[] = XLSX.utils.sheet_to_json(ws)
      setParsed(rows.map(row => ({
        name: row.name || row.Name,
        date: row.date || row.Date,
        type: row.type || row.Type || 'PUBLIC',
        notes: row.notes || row.Notes
      })).filter(r => r.name && r.date))
    }
  }

  return (
    <div className="space-y-6">
      <div className="bg-blue-50 border border-blue-100 rounded-2xl p-5 shadow-inner">
        <p className="text-[11px] font-bold text-blue-600 uppercase tracking-[0.2em] mb-3 flex items-center gap-2">
          <FileText size={14} />
          CSV/Excel Structure
        </p>
        <div className="bg-white/80 border border-blue-100 rounded-xl p-3">
          <code className="text-xs font-bold text-blue-700 tracking-tighter">
            name, date (DD-MM-YYYY), type (PUBLIC/FLOATER), notes
          </code>
        </div>
      </div>

      <div 
        onClick={() => document.getElementById('holiday-file')?.click()}
        className="border-2 border-dashed border-slate-200 rounded-3xl p-16 text-center cursor-pointer hover:border-blue-400 hover:bg-blue-50/30 transition-all group active:scale-[0.99]"
      >
        <input id="holiday-file" type="file" hidden onChange={e => e.target.files?.[0] && handleFile(e.target.files[0])} accept=".csv,.xlsx,.xls" />
        <div className="w-16 h-16 rounded-2xl bg-blue-50 flex items-center justify-center text-blue-600 mx-auto mb-6 group-hover:scale-110 transition-transform shadow-inner">
          <Upload size={28} />
        </div>
        <p className="text-lg font-bold text-slate-900 leading-tight">
          {fileName || 'Click to upload holiday schedule'}
        </p>
        <p className="text-[11px] font-bold text-slate-400 uppercase tracking-widest mt-2">
          Supports CSV and Excel files
        </p>
      </div>

      {parsed.length > 0 && (
        <motion.div 
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          className="bg-emerald-50 border border-emerald-100 rounded-2xl p-5 flex items-center justify-between shadow-sm"
        >
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-full bg-emerald-100 flex items-center justify-center text-emerald-600 shadow-inner">
              <CheckCircle2 size={20} />
            </div>
            <div>
              <p className="text-sm font-bold text-emerald-900">{parsed.length} holidays detected</p>
              <p className="text-[10px] font-bold text-emerald-600 uppercase tracking-widest">Ready for import</p>
            </div>
          </div>
          <button 
            onClick={() => uploadMutation.mutate(parsed)}
            disabled={uploadMutation.isPending}
            className="bg-emerald-600 text-white px-6 py-2.5 rounded-xl text-[11px] font-bold uppercase tracking-widest hover:bg-emerald-700 shadow-lg shadow-emerald-100 transition-all active:scale-95 disabled:opacity-50"
          >
            {uploadMutation.isPending ? 'Importing...' : 'Start Import'}
          </button>
        </motion.div>
      )}
    </div>
  )
}

